} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","prefix","product","fontWeight","hold","accent","fontFamily","ink","background","scale","delay","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  prefix: "Motion for",
  product: "remocn",
  fontWeight: 500,
  hold: 22,
  accent: "#3B5BFD",
  fontFamily: "Manrope",
  scale: 1,
  delay: 0,
  speed: 1,
};

type BracketIndexElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof BracketIndexBase>;

const BracketIndexInner = forwardRef<
  HTMLDivElement,
  BracketIndexElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<BracketIndex>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <BracketIndexBase
          {...(componentProps as unknown as ComponentProps<typeof BracketIndexBase>)}
        />
      </div>
    </Sequence>
  );
});

export const BracketIndex = Interactive.withSchema({
  Component: BracketIndexInner,
  componentName: "<BracketIndex>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
